-- Read-only fingerprints; no identities, credentials or personal values emitted.
begin read only; with cs as(select id from public.federation_competitions where club_id='a48efe2f-c218-633e-6be6-4ce26e61f5cd' and season_id='94b6c5ab-ecc9-b4a5-4a2a-ad8d5446ff2e'), fs as(select m.id from public.federation_matches m join public.federation_groups g on g.id=m.group_id where g.competition_id in(select id from cs)), op as(select match_id from public.stats_matches where club_id='a48efe2f-c218-633e-6be6-4ce26e61f5cd' union select b.pilot_match_id from public.basic_match_contexts b where b.catalogue_match_id in(select id from fs)) select 'pilot_events' as name,count(*)::int as rows,md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),'')) as fingerprint from public.pilot_events t where match_id in(select match_id from op) union all select 'pilot_operator_state' as name,count(*)::int as rows,md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),'')) as fingerprint from public.pilot_operator_state t where match_id in(select match_id from op) union all select 'stats_events' as name,count(*)::int as rows,md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),'')) as fingerprint from public.stats_events t where match_id in(select match_id from op) union all select 'stats_sessions' as name,count(*)::int as rows,md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),'')) as fingerprint from public.stats_sessions t where match_id in(select match_id from op) union all select 'stats_assignments' as name,count(*)::int as rows,md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),'')) as fingerprint from public.stats_assignments t where match_id in(select match_id from op) union all select 'pilot_members' as name,count(*)::int as rows,md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),'')) as fingerprint from public.pilot_members t where match_id in(select match_id from op) union all select 'pilot_players' as name,count(*)::int as rows,md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),'')) as fingerprint from public.pilot_players t where match_id in(select match_id from op) union all select 'basic_match_contexts' as name,count(*)::int as rows,md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),'')) as fingerprint from public.basic_match_contexts t where pilot_match_id in(select match_id from op) union all select 'federation_matches' as name,count(*)::int as rows,md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),'')) as fingerprint from public.federation_matches t where id in(select id from fs) union all select 'federation_team_roster' as name,count(*)::int as rows,md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),'')) as fingerprint from public.federation_team_roster t where entry_id in(select id from public.federation_team_entries where competition_id in(select id from cs)) union all select 'teams' as name,count(*)::int as rows,md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),'')) as fingerprint from public.teams t where club_id='a48efe2f-c218-633e-6be6-4ce26e61f5cd' union all select 'club_memberships' as name,count(*)::int as rows,md5(coalesce(string_agg(to_jsonb(t)::text,'' order by to_jsonb(t)::text),'')) as fingerprint from public.club_memberships t where club_id='a48efe2f-c218-633e-6be6-4ce26e61f5cd'; rollback;
